From Stdlib Require Import Lia.
From Ltac2 Require Ltac2.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Lemma nd_ex1 : forall (A1 : Type) (P : A1 -> Prop) (Q : Prop), (forall a1, P a1 -> Q) -> (exists a1, P a1) -> Q.
Proof. intros A1 P Q K H. destruct H as (a1 & HP). exact (K a1 HP). Qed.
Lemma nd_ex2 : forall (A1 A2 : Type) (P : A1 -> A2 -> Prop) (Q : Prop), (forall a1 a2, P a1 a2 -> Q) -> (exists a1 a2, P a1 a2) -> Q.
Proof. intros A1 A2 P Q K H. destruct H as (a1 & a2 & HP). exact (K a1 a2 HP). Qed.
