Module NDL2.
  Import Ltac2.Ltac2.
  Ltac2 ind_of (c : constr) : inductive option :=
    match Constr.Unsafe.kind c with Constr.Unsafe.Ind i _ => Some i | _ => None end.
  Ltac2 is_ind (f : constr) (r : constr) : bool :=
    match ind_of f, ind_of r with Some i, Some j => Ind.equal i j | _, _ => false end.
  (* [comment removed for export] *)
  Ltac2 rec cnt_ex (t0 : constr) (lim : int) : int :=
    if Int.le lim 0 then 0 else
    let t := Std.eval_hnf t0 in
    match Constr.Unsafe.kind t with
    | Constr.Unsafe.App f args =>
        if Int.equal (Array.length args) 2 then
          if is_ind f constr:(@ex) then
            match Constr.Unsafe.kind (Array.get args 1) with
            | Constr.Unsafe.Lambda _ b => Int.add 1 (cnt_ex b (Int.sub lim 1))
            | _ => 0
            end
          else 0
        else 0
    | _ => 0
    end.
  (* [comment removed for export] *)
  Ltac2 rec cnt_and (t0 : constr) (lim : int) : int :=
    if Int.le lim 0 then 0 else
    let t := Std.eval_hnf t0 in
    match Constr.Unsafe.kind t with
    | Constr.Unsafe.App f args =>
        if Int.equal (Array.length args) 2 then
          if is_ind f constr:(@and) then Int.add 1 (cnt_and (Array.get args 1) (Int.sub lim 1)) else 0
        else 0
    | _ => 0
    end.
  Ltac2 rec nat_of_int (n : int) : constr := if Int.le n 0 then constr:(O) else let m := nat_of_int (Int.sub n 1) in constr:(S $m).
  Ltac2 rec int_of_nat (c : constr) : int :=
    match Constr.Unsafe.kind c with
    | Constr.Unsafe.App _ args => Int.add 1 (int_of_nat (Array.get args 0))
    | _ => 0
    end.
  Ltac2 intro_temps (n : int) : ident list :=
    List.map (fun _ => let id := Fresh.in_goal @ndt in Std.intros false [Std.IntroNaming (Std.IntroIdentifier id)]; id) (List.seq 0 1 n).
  (* [comment removed for export] *)
  Ltac2 rec go (k : int) : unit :=
    if Int.le k 1 then () else
    let t := match! goal with [ |- ?t -> _ ] => t | [ |- _ ] => Control.zero (Tactic_failure (Some (Message.of_string "nd: no premise"))) end in
    let cex := cnt_ex t (Int.sub k 1) in
    if Int.gt cex 0 then
      (let n := nat_of_int cex in ltac1:(n |- nd_ex_ap n) (Ltac1.of_constr n);
       let rest := Int.sub k cex in
       if Int.gt rest 1 then (let ids := intro_temps cex in go rest; Std.revert ids) else ())
    else
      let cand := cnt_and t (Int.sub k 1) in
      if Int.gt cand 0 then
        (let m := nat_of_int (Int.add cand 1) in ltac1:(m |- nd_and_ap m) (Ltac1.of_constr m);
         let rest := Int.sub k cand in
         if Int.gt rest 1 then (let ids := intro_temps cand in go rest; Std.revert ids) else ())
      else Control.zero (Tactic_failure (Some (Message.of_string "nd: not an ex/and spine"))).
  Ltac2 go1 (k : Ltac1.t) : unit :=
    match Ltac1.to_constr k with Some c => go (int_of_nat c) | None => Control.zero (Tactic_failure None) end.
  Ltac2 dump (tag : string) (k : int) : unit :=
    let hs := Control.hyps () in
    let names := List.map (fun h => let (id, _, _) := h in id) hs in
    Message.print (Message.concat (Message.of_string (String.app (String.app "NDDUMP " tag) " :"))
      (List.fold_left (fun acc id => Message.concat acc (Message.concat (Message.of_string " ") (Message.of_ident id))) (Message.of_string "") names));
    let n := List.length hs in
    List.iter (fun h => let (id, _, ty) := h in Message.print (Message.concat (Message.of_string (String.app (String.app "NDTY " tag) " ")) (Message.concat (Message.of_ident id) (Message.concat (Message.of_string " : ") (Message.of_constr ty)))))
      (List.skipn (Int.sub n k) hs);
    Message.print (Message.concat (Message.of_string (String.app (String.app "NDGOAL " tag) " ")) (Message.of_constr (Control.goal ()))).
  Ltac2 dump1 (tag : Ltac1.t) (k : Ltac1.t) : unit :=
    match Ltac1.to_constr tag, Ltac1.to_constr k with
    | Some t, Some c => dump (Message.to_string (Message.of_int (int_of_nat t))) (int_of_nat c)
    | _, _ => ()
    end.
End NDL2.
(* [comment removed for export] *)
Ltac nd_dump tag k := let f := ltac2:(tag k |- NDL2.dump1 tag k) in f tag k.
Ltac nd_curry H k := try clearbody H; revert H; let f := ltac2:(k |- NDL2.go1 k) in f k.
Module NDL3.
  Import Ltac2.Ltac2.
  Ltac2 mutable debug : bool := false.
  (* [comment removed for export] *)
  Ltac2 fb_curry (h : ident) (k : int) : unit :=
    (if debug then Message.print (Message.of_string "NDFB") else ());
    let rec peel (cur : ident) (n : int) (acc : ident list) : ident list :=
      if Int.le n 1 then List.rev (cur :: acc) else
      let a := Fresh.fresh (Fresh.Free.of_goal ()) @ndf in
      let b := Fresh.fresh (Fresh.Free.union (Fresh.Free.of_goal ()) (Fresh.Free.of_ids [a])) @ndf in
      ltac1:(c a b |- destruct c as [a b]) (Ltac1.of_ident cur) (Ltac1.of_ident a) (Ltac1.of_ident b);
      peel b (Int.sub n 1) (a :: acc) in
    let temps := peel h k [] in
    Std.revert temps.
  (* [comment removed for export] *)
  Ltac2 curry (k : int) : unit :=
    match Control.case (fun () => NDL2.go k) with
    | Val _ => ()
    | Err _ => let h := Fresh.in_goal @ndF in Std.intros false [Std.IntroNaming (Std.IntroIdentifier h)]; fb_curry h k
    end.
  Ltac2 curry1 (k : Ltac1.t) : unit :=
    match Ltac1.to_int k with
    | Some n => Control.enter (fun () => curry n)
    | None =>
      match Ltac1.to_constr k with
      | Some c => let n := NDL2.int_of_nat c in Control.enter (fun () => curry n)
      | None => Control.zero (Tactic_failure (Some (Message.of_string "nd_pre: bad component count")))
      end
    end.
  (* [comment removed for export] *)
  Ltac2 post () : unit := Control.enter (fun () =>
    let hs := Control.hyps () in
    let rec after l := match l with [] => [] | x :: r => let (id, _, _) := x in if Ident.equal id @ndEnd__ then r else after r end in
    let news := after hs in
    List.iter (fun x => let (id, _, _) := x in Std.move id (Std.MoveAfter @ndMark__)) news;
    Std.clear [@ndMark__; @ndEnd__]).
End NDL3.
Module NDL4.
  Import Ltac2.Ltac2.
  Ltac2 try_report (t1 : Ltac1.t) (t2 : Ltac1.t) : unit :=
    match Control.case (fun () => Ltac1.run t1) with
    | Val _ => ()
    | Err e => Message.print (Message.concat (Message.of_string "NDERR ") (Message.of_exn e)); Ltac1.run t2
    end.
End NDL4.
Ltac nd_try t1 t2 := let f := ltac2:(a b |- NDL4.try_report a b) in f t1 t2.
(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac nd_pre_var H k :=
  lazymatch type of H with forall _, _ => fail 100 "ND-PARTIAL: destruct would generate side goals here (exclude this site)" | _ => idtac end;
  pose proof I as ndMark__; move ndMark__ before H; pose proof I as ndEnd__; (try clearbody H); revert H;
  let f := ltac2:(k |- NDL3.curry1 k) in f k.
Ltac nd_pre H k := first [ is_var H; nd_pre_var H k | let h := fresh "ndH" in pose proof H as h; nd_pre_var h k ].
Ltac nd_post := ltac2:(NDL3.post ()).
Module NDL5.
  Import Ltac2.Ltac2.
  (* [comment removed for export] *)
  Ltac2 rec cnt_and_syn (t : constr) : int :=
    match Constr.Unsafe.kind t with
    | Constr.Unsafe.App f args =>
        if Int.equal (Array.length args) 2 then
          if NDL2.is_ind f constr:(@and) then Int.add 1 (cnt_and_syn (Array.get args 1)) else 0
        else 0
    | _ => 0
    end.
  Ltac2 intro_fresh (base : ident) (n : int) : unit :=
    List.iter (fun _ => let id := Fresh.in_goal base in Std.intros false [Std.IntroNaming (Std.IntroIdentifier id)]) (List.seq 0 1 n).
  (* [comment removed for export] *)
  Ltac2 exs_curry () : unit := Control.enter (fun () =>
    let t := match! goal with [ |- ?t -> _ ] => t end in
    let n := NDL2.cnt_ex t 1000 in
    NDL3.curry (Int.add n 1); intro_fresh @x n).
  (* [comment removed for export] *)
  Ltac2 ands_curry () : unit := Control.enter (fun () =>
    let t := match! goal with [ |- ?t -> _ ] => t end in
    let n := cnt_and_syn t in
    NDL3.curry (Int.add n 1); intro_fresh @PC n).
End NDL5.
(* [comment removed for export] *)
Ltac nd_destruct_exs PO :=
  let T := type of PO in let T' := eval hnf in T in
  lazymatch T' with
  | ex _ => pose proof I as ndMark__; move ndMark__ before PO; pose proof I as ndEnd__; (try clearbody PO); revert PO;
            ltac2:(NDL5.exs_curry ()); intro PO; nd_post
  | _ => idtac
  end.
Ltac nd_destruct_ands PO :=
  lazymatch type of PO with
  | _ /\ _ => pose proof I as ndMark__; move ndMark__ before PO; pose proof I as ndEnd__; (try clearbody PO); revert PO;
            ltac2:(NDL5.ands_curry ()); intro PO; nd_post
  | _ => idtac
  end.


